from .serializers import MemberSerializer, UserRoleUpdateSerializer


@api_view(['POST'])
@permission_classes([AllowAny])
def login_user(request):
    try:
        username = request.data.get('username', '').lower()
        password = request.data.get('password', '')
        ad_server = settings.AD_SERVER
        ad_domain = settings.AD_DOMAIN
        ad_base_dn = settings.AD_BASE_DN

        if not Member.objects.filter(username=username).exists():
            try:
                server = ldap3.Server(ad_server, get_info=ldap3.ALL)
                connect = ldap3.Connection(server, user=f'{ad_domain}\\{username}', password=password)

                if connect.bind():
                    search_filter = f'(sAMAccountName={ldap3.utils.conv.escape_filter_chars(username)})'
                    attributes = ['sAMAccountName', 'displayName', 'mail', 'department', 'employeeID']
                    connect.search(search_base=ad_base_dn, search_filter=search_filter, attributes=attributes)

                    if connect.entries:
                        entry = connect.entries[0]
                        new_member = Member.objects.create(
                            emp_id=entry.employeeID.value,
                            username=username,
                            name=entry.displayName.value,
                            email=entry.mail.value,
                            department=entry.department.value,
                            role_level=RoleLevel.USER,
                        )
                        token, _ = Token.objects.get_or_create(user=new_member)
                        serializer = MemberSerializer(new_member)
                        return Response(
                            {"detail": "success", "token": token.key, "data": serializer.data, "route_data": None},
                            status=status.HTTP_201_CREATED
                        )
                else:
                    return Response(
                        {"detail": "Failure, This user not found in Active Directory"},
                        status=status.HTTP_404_NOT_FOUND
                    )
            except Exception as e:
                return Response(
                    {"detail": "Credentials are invalid. Please check your username or password."},
                    status=status.HTTP_500_INTERNAL_SERVER_ERROR
                )
        else:
            user = get_object_or_404(Member, username=username)
            if user.is_superuser or user.is_local:
                if not user.check_password(password):
                    return Response(
                        {"detail": "Username or password is incorrect."},
                        status=status.HTTP_404_NOT_FOUND
                    )
            else:
                _, _, valid = validate_credentials(username, ad_server, ad_domain, password)
                if not valid:
                    return Response(
                        {"detail": "Credentials are invalid. Please check your username or password."},
                        status=status.HTTP_409_CONFLICT
                    )

            token, _ = Token.objects.get_or_create(user=user)
            serializer = MemberSerializer(instance=user)
            return Response(
                {"detail": "success", "token": token.key, "data": serializer.data, "route_data": None},
                status=status.HTTP_200_OK
            )

    except Exception as e:
        return Response(
            {"detail": f"Failure, data as provided is incorrect. Error: {str(e)}"},
            status=status.HTTP_400_BAD_REQUEST
        )


def validate_credentials(username, ad_server, ad_domain, password):
    try:
        server = ldap3.Server(ad_server, get_info=ldap3.ALL)
        connect = ldap3.Connection(server, user=f'{ad_domain}\\{username}', password=password)
        if connect.bind():
            return "", "", True
        else:
            return "1326", "The user name or password is incorrect.", False
    except Exception as e:
        return "1326", "The user name or password is incorrect.", False


@api_view(['POST'])
@authentication_classes([SessionAuthentication, TokenAuthentication])
@permission_classes([IsAuthenticated])
def logout_user(request):
    try:
        auth_header = request.headers.get('Authorization', '')
        parts = auth_header.split(' ')
        if len(parts) != 2:
            return Response({"detail": "Token not provided"}, status=status.HTTP_400_BAD_REQUEST)

from rest_framework import serializers
from .models import Member
from core.models import ProductionArea
from core.permissions import has_all_areas


class MemberSerializer(serializers.ModelSerializer):
    role_level_display = serializers.CharField(source='get_role_level_display', read_only=True)
    production_areas = serializers.PrimaryKeyRelatedField(many=True, read_only=True)
    production_area_names = serializers.SerializerMethodField()
    has_all_areas = serializers.SerializerMethodField()

    class Meta:
        model = Member
        fields = [
            'id', 'emp_id', 'username', 'name', 'email', 'department', 'image_url',
            'role_level', 'role_level_display', 'is_staff', 'is_local', 'date_joined',
            'production_areas', 'production_area_names', 'has_all_areas',
        ]

    def get_has_all_areas(self, obj):
        return has_all_areas(obj)

    def get_production_area_names(self, obj):
        qs = ProductionArea.objects.all() if has_all_areas(obj) else obj.production_areas.all()
        return list(qs.order_by('name').values_list('name', flat=True))


class EmployeeIdQuerySerializer(serializers.Serializer):
    emp_id = serializers.CharField(required=True, max_length=100)

    def validate_emp_id(self, value):
        if not Member.objects.filter(emp_id=value).exists():
            raise serializers.ValidationError("Employee ID does not exist.")
        return value

        raise PermissionDenied('Members cannot be deleted through this API.')


@api_view(['GET'])
@authentication_classes([SessionAuthentication, TokenAuthentication])
@permission_classes([IsAuthenticated])
def current_member(request):
    try:
        member = Member.objects.filter(username=request.user.username).first()
        if not member:
            return Response({"detail": "Member not found"}, status=status.HTTP_404_NOT_FOUND)
        serializer = MemberSerializer(member)
        return Response(serializer.data, status=status.HTTP_200_OK)
    except Exception as e:
        return Response({"detail": str(e)}, status=status.HTTP_500_INTERNAL_SERVER_ERROR)

@api_view(['GET'])
@authentication_classes([SessionAuthentication, TokenAuthentication])
@permission_classes([IsAuthenticated])
def get_member_by_emp_id(request, emp_id):
    try:
        member = get_object_or_404(Member, emp_id=emp_id)
        serializer = MemberSerializer(member)
        return Response(serializer.data, status=status.HTTP_200_OK)
    except Exception as e:
        return Response({"detail": str(e)}, status=status.HTTP_500_INTERNAL_SERVER_ERROR)

