import * as SecureStore from 'expo-secure-store';
import { createContext, useCallback, useContext, useEffect, useMemo, useState, type ReactNode } from 'react';

import { DEFAULT_API_URL } from '@/constants/config';
import { api, configureApi, setUnauthorizedHandler, type Member } from '@/lib/api';

const KEYS = {
  serverUrl: 'pms.serverUrl',
  token: 'pms.token',
  member: 'pms.member',
  area: 'pms.area',
} as const;

type Session = {
  ready: boolean;
  serverUrl: string;
  member: Member | null;
  area: string | null;
  signIn: (username: string, password: string) => Promise<void>;
  selectArea: (area: string) => Promise<void>;
  /** Drops the token on this tablet only. `auth/logout/` is not called: it deletes the member's only
   *  token and would sign them out of the web too. */
  signOut: () => Promise<void>;
  setServerUrl: (url: string) => Promise<void>;
};

const SessionContext = createContext<Session | null>(null);

async function save(key: string, value: string | null) {
  if (value === null) await SecureStore.deleteItemAsync(key);
  else await SecureStore.setItemAsync(key, value);
}

export function SessionProvider({ children }: { children: ReactNode }) {
  const [ready, setReady] = useState(false);
  const [serverUrl, setServerUrlState] = useState(DEFAULT_API_URL);
  const [member, setMember] = useState<Member | null>(null);
  const [area, setArea] = useState<string | null>(null);

  const signOut = useCallback(async () => {
    configureApi(api.defaults.baseURL ?? DEFAULT_API_URL, null);
    setMember(null);
    setArea(null);
    await Promise.all([save(KEYS.token, null), save(KEYS.member, null), save(KEYS.area, null)]);
  }, []);

  const selectArea = useCallback(async (name: string) => {
    setArea(name);
    await save(KEYS.area, name);
  }, []);

  useEffect(() => {
    setUnauthorizedHandler(() => void signOut());
    return () => setUnauthorizedHandler(null);
  }, [signOut]);

  // Restore the last session, then refresh the member in the background (areas may have changed).
  useEffect(() => {
    (async () => {
      const [url, token, memberJson, savedArea] = await Promise.all([
        SecureStore.getItemAsync(KEYS.serverUrl),
        SecureStore.getItemAsync(KEYS.token),
        SecureStore.getItemAsync(KEYS.member),
        SecureStore.getItemAsync(KEYS.area),
      ]);
      const baseUrl = url ?? DEFAULT_API_URL;
      setServerUrlState(baseUrl);
      configureApi(baseUrl, token);
      if (token && memberJson) {
        setMember(JSON.parse(memberJson) as Member);
        setArea(savedArea);
      }
      setReady(true);

      if (!token) return;
      try {
        const { data } = await api.get<Member>('auth/current-member/');
        setMember(data);
        await save(KEYS.member, JSON.stringify(data));
        if (savedArea && !data.production_area_names.includes(savedArea)) {
          setArea(null);
          await save(KEYS.area, null);
        }
      } catch {
        // Offline: keep the saved member. A 401 is handled by the interceptor.
      }
    })();
  }, []);

  const signIn = useCallback(
    async (username: string, password: string) => {
      const { data } = await api.post<{ token: string; data: Member }>('auth/login/', { username, password });
      configureApi(api.defaults.baseURL ?? DEFAULT_API_URL, data.token);
      await Promise.all([save(KEYS.token, data.token), save(KEYS.member, JSON.stringify(data.data))]);
      setMember(data.data);
      const areas = data.data.production_area_names;
      if (areas.length === 1) await selectArea(areas[0]);
    },
    [selectArea],
  );

  const setServerUrl = useCallback(async (url: string) => {
    // A token belongs to one backend, so switching servers signs out.
    await signOut();
    configureApi(url, null);
    setServerUrlState(url);
    await save(KEYS.serverUrl, url);
  }, [signOut]);

  const value = useMemo(
    () => ({ ready, serverUrl, member, area, signIn, selectArea, signOut, setServerUrl }),
    [ready, serverUrl, member, area, signIn, selectArea, signOut, setServerUrl],
  );
  return <SessionContext.Provider value={value}>{children}</SessionContext.Provider>;
}

export function useSession(): Session {
  const session = useContext(SessionContext);
  if (!session) throw new Error('useSession must be used inside <SessionProvider>');
  return session;
}

