import { ActivityIndicator, Pressable, StyleSheet, Text, type PressableProps } from 'react-native';

import { PmsColors, PmsSizes } from '@/constants/pms-theme';

type Props = Omit<PressableProps, 'children'> & {
  title: string;
  variant?: 'primary' | 'secondary';
  loading?: boolean;
};

export function PmsButton({ title, variant = 'primary', loading = false, disabled, style, ...rest }: Props) {
  const isPrimary = variant === 'primary';
  const inactive = disabled || loading;
  return (
    <Pressable
      accessibilityRole="button"
      disabled={inactive}
      style={(state) => [
        styles.base,
        isPrimary ? styles.primary : styles.secondary,
        state.pressed && (isPrimary ? styles.primaryPressed : styles.secondaryPressed),
        inactive && styles.disabled,
        typeof style === 'function' ? style(state) : style,
      ]}
      {...rest}>
      {loading ? (
        <ActivityIndicator color={isPrimary ? PmsColors.textOnPrimary : PmsColors.primary} />
      ) : (
        <Text style={[styles.label, !isPrimary && styles.secondaryLabel]} maxFontSizeMultiplier={1.3}>
          {title}
        </Text>
      )}
    </Pressable>
  );
}

const styles = StyleSheet.create({
  base: {
    minHeight: PmsSizes.primaryButton,
    paddingHorizontal: PmsSizes.pad,
    borderRadius: PmsSizes.radius,
    alignItems: 'center',
    justifyContent: 'center',
  },
  primary: { backgroundColor: PmsColors.primary },
  primaryPressed: { backgroundColor: PmsColors.primaryPressed },
  secondary: { backgroundColor: PmsColors.surface, borderWidth: 2, borderColor: PmsColors.primary },
  secondaryPressed: { backgroundColor: '#E0F0FA' },
  disabled: { opacity: 0.5 },
  label: { color: PmsColors.textOnPrimary, fontSize: 20, fontWeight: '700' },
  secondaryLabel: { color: PmsColors.primary },
});

