import { router } from 'expo-router';
import { useRef, useState } from 'react';
import { KeyboardAvoidingView, Pressable, ScrollView, StyleSheet, Text, TextInput, View } from 'react-native';
import { SafeAreaView } from 'react-native-safe-area-context';

import { PmsButton } from '@/components/pms/button';
import { PmsTextField } from '@/components/pms/text-field';
import { PmsColors, PmsSizes } from '@/constants/pms-theme';
import { errorMessage } from '@/lib/api';
import { useSession } from '@/lib/session';

export default function SignInScreen() {
  const { signIn, serverUrl } = useSession();
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const passwordRef = useRef<TextInput>(null);

  const canSubmit = username.trim() !== '' && password !== '' && !busy;

  async function submit() {
    if (!canSubmit) return;
    setBusy(true);
    setError(null);
    try {
      await signIn(username.trim(), password);
      // The layout's guards move on to area selection or the equipment list.
    } catch (e) {
      setError(errorMessage(e));
      setBusy(false);
    }
  }

  return (
    <SafeAreaView style={styles.screen}>
      {/* Long-press the logo for 3 s to reach Server settings; technicians should not stumble on it. */}
      <Pressable
        style={styles.brand}
        delayLongPress={3000}
        onLongPress={() => router.push('/server-settings')}
        accessibilityLabel="PMS+">
        <Text style={styles.logo}>PMS+</Text>
        <Text style={styles.tagline}>Preventive Maintenance</Text>
      </Pressable>

      <KeyboardAvoidingView style={styles.formSide} behavior="height">
        <ScrollView contentContainerStyle={styles.formScroll} keyboardShouldPersistTaps="handled">
          <View style={styles.form}>
            <Text style={styles.title}>Sign in</Text>
            <PmsTextField
              label="Username"
              placeholder="Windows (AD) username"
              value={username}
              onChangeText={setUsername}
              autoCapitalize="none"
              autoCorrect={false}
              autoComplete="username"
              returnKeyType="next"
              onSubmitEditing={() => passwordRef.current?.focus()}
              submitBehavior="submit"
            />
            <PmsTextField
              ref={passwordRef}
              label="Password"
              value={password}
              onChangeText={setPassword}
              secureTextEntry
              autoComplete="password"
              returnKeyType="go"
              onSubmitEditing={submit}
            />
            {error && <Text style={styles.error}>{error}</Text>}
            <PmsButton title="Sign in" onPress={submit} disabled={!canSubmit} loading={busy} />
            <Text style={styles.server} numberOfLines={1}>
              Server: {serverUrl}
            </Text>
          </View>
        </ScrollView>
      </KeyboardAvoidingView>
    </SafeAreaView>
  );
}

const styles = StyleSheet.create({
  screen: { flex: 1, flexDirection: 'row', backgroundColor: PmsColors.background },
  brand: {
    flex: 2,
    backgroundColor: PmsColors.primary,
    alignItems: 'center',
    justifyContent: 'center',
    padding: PmsSizes.pad,
  },
  logo: { fontSize: 72, fontWeight: '800', color: PmsColors.textOnPrimary },
  tagline: { fontSize: 20, color: PmsColors.textOnPrimary, opacity: 0.85 },
  formSide: { flex: 3 },
  formScroll: { flexGrow: 1, justifyContent: 'center', padding: PmsSizes.pad },
  form: { width: '100%', maxWidth: 480, alignSelf: 'center', gap: PmsSizes.gap },
  title: { fontSize: 32, fontWeight: '700', color: PmsColors.text },
  error: { fontSize: 16, color: PmsColors.danger },
  server: { fontSize: 13, color: PmsColors.textSecondary, textAlign: 'center' },
});

