import { router } from 'expo-router';
import { Pressable, ScrollView, StyleSheet, Text, View } from 'react-native';
import { SafeAreaView } from 'react-native-safe-area-context';

import { PmsButton } from '@/components/pms/button';
import { PmsColors, PmsSizes } from '@/constants/pms-theme';
import { useSession } from '@/lib/session';

export default function SelectAreaScreen() {
  const { member, area: currentArea, selectArea, signOut } = useSession();
  const areas = member?.production_area_names ?? [];

  async function pick(name: string) {
    await selectArea(name);
    router.replace('/');
  }

  return (
    <SafeAreaView style={styles.screen}>
      <View style={styles.header}>
        <View>
          <Text style={styles.hello}>Hello, {member?.name ?? member?.username}</Text>
          <Text style={styles.title}>Choose a production area</Text>
        </View>
        <PmsButton title="Sign out" variant="secondary" onPress={signOut} />
      </View>

      {areas.length === 0 ? (
        <Text style={styles.empty}>No production area is assigned to you. Ask your manager to add one on the web.</Text>
      ) : (
        <ScrollView contentContainerStyle={styles.grid}>
          {areas.map((name) => (
            <Pressable
              key={name}
              accessibilityRole="button"
              onPress={() => pick(name)}
              style={({ pressed }) => [styles.card, name === currentArea && styles.cardCurrent, pressed && styles.cardPressed]}>
              <Text style={styles.cardText} maxFontSizeMultiplier={1.3}>
                {name}
              </Text>
            </Pressable>
          ))}
        </ScrollView>
      )}
    </SafeAreaView>
  );
}

const styles = StyleSheet.create({
  screen: { flex: 1, backgroundColor: PmsColors.background, padding: PmsSizes.pad, gap: PmsSizes.pad },
  header: { flexDirection: 'row', justifyContent: 'space-between', alignItems: 'center' },
  hello: { fontSize: 18, color: PmsColors.textSecondary },
  title: { fontSize: 32, fontWeight: '700', color: PmsColors.text },
  empty: { fontSize: 20, color: PmsColors.textSecondary },
  grid: { flexDirection: 'row', flexWrap: 'wrap', gap: PmsSizes.gap },
  card: {
    minWidth: 260,
    flexGrow: 1,
    flexBasis: 260,
    minHeight: 96,
    padding: PmsSizes.pad,
    borderRadius: PmsSizes.radius,
    borderWidth: 2,
    borderColor: PmsColors.border,
    backgroundColor: PmsColors.surface,
    justifyContent: 'center',
  },
  cardCurrent: { borderColor: PmsColors.primary },
  cardPressed: { backgroundColor: '#E0F0FA' },
  cardText: { fontSize: 22, fontWeight: '700', color: PmsColors.text },
});

