          <PmsButton title="Sign out" variant="secondary" onPress={signOut} />
        </View>
      </View>
      <View style={styles.body}>
        <Text style={styles.placeholder}>Equipment list — coming next</Text>
      </View>
    </SafeAreaView>
  );
}

const styles = StyleSheet.create({
  screen: { flex: 1, backgroundColor: PmsColors.background },
