import React, { useState } from 'react'
import ItemDetailDialog from './ItemDetailDialog'
import { Image, CheckCircle2, AlertTriangle, MapPin, ChevronRight, Clock, Box, PackagePlus } from 'lucide-react'
import { APP_MDEFECT_BACKEND_URL } from '../../../lib/urls'
import { WARNING_DAYS } from '@/lib/globalConstant'

const getPeriodStatus = (p) => {
  if (p.is_overdue) return 'overdue'
  if (p.days_until_due != null && p.days_until_due <= WARNING_DAYS) return 'warning'
  if (p.days_until_due != null) return 'on_time'
  if (p.pending_approval && p.last_pm_date === null) return 'pending_approval'
  return 'new'
}

const STATUS_RANK = { overdue: 0, warning: 1, new: 2, pending_approval: 3, on_time: 4 }

const getItemStatus = (periods) => {
  const list = periods ?? []
  if (list.length === 0) return 'new'
  return list.reduce((worst, p) => {
    const s = getPeriodStatus(p)
    return STATUS_RANK[s] < STATUS_RANK[worst] ? s : worst
  }, 'on_time')
}

const getPeriodName = (p) => p.period_type ?? p.name ?? p.pm_type ?? null

const statusInfo = (status, periods) => {
  const list = periods ?? []
  if (status === 'overdue') {
    const overdues = list.filter(p => p.is_overdue)
    if (!overdues.length) return {}
    const worst = overdues.reduce((a, b) =>
      Math.abs(a.days_until_due ?? 0) >= Math.abs(b.days_until_due ?? 0) ? a : b
    )
    const d = worst.days_until_due != null ? Math.abs(worst.days_until_due) : null
    return { dayLabel: d != null ? `${d} days overdue` : null, period: getPeriodName(worst) }
  }
  if (status === 'warning') {
    const warnings = list.filter(p => !p.is_overdue && p.days_until_due != null && p.days_until_due <= WARNING_DAYS)
    if (!warnings.length) return {}
    const soonest = warnings.reduce((a, b) => a.days_until_due <= b.days_until_due ? a : b)
    return { dayLabel: `${soonest.days_until_due} days left`, period: getPeriodName(soonest) }
  }
  return {}
}

const STATUS_CFG = {
  overdue: {
    accentBar: 'bg-red-700',
    dot: 'bg-red-600 animate-pulse',
    pill: 'bg-red-50 text-red-600 border border-red-200',
    dayText: 'text-red-600',
    Icon: AlertTriangle,
    label: 'Overdue',
  },
  warning: {
    accentBar: 'bg-amber-600',
    dot: 'bg-amber-500',
    pill: 'bg-amber-50 text-amber-800 border border-amber-200',

