import { Pressable, StyleSheet, Text, View } from "react-native";

import { PmsColors, PmsSizes } from "@/constants/pms-theme";
import { equipmentStatus, periodLabel, type EquipmentSummary, type PmStatus } from "@/lib/equipment";

export const STATUS_STYLE: Record<PmStatus, { color: string; label: string }> = {
  overdue: { color: PmsColors.overdue, label: "Overdue" },
  due: { color: PmsColors.due, label: "Due soon" },
  on_time: { color: PmsColors.onTime, label: "On time" },
  pending: { color: PmsColors.pending, label: "Pending approval" },
  new: { color: PmsColors.textSecondary, label: "No schedule" },
};

function detailText(status: PmStatus, days: number | null | undefined): string | null {
  if (days == null) return null;
  if (status === "overdue") return `${Math.abs(days)} days overdue`;
  return `${days} days left`;
}

type Props = { item: EquipmentSummary; onPress: () => void };

export function EquipmentCard({ item, onPress }: Props) {
  const { status, period } = equipmentStatus(item);
  const style = STATUS_STYLE[status];
  const detail = detailText(status, period?.days_until_due);
  const waiting = item.periods.some((p) => p.pending_approval);

  return (
    <Pressable
      accessibilityRole="button"
      onPress={onPress}
      style={({ pressed }) => [styles.card, pressed && styles.pressed]}>
      <View style={[styles.accent, { backgroundColor: style.color }]} />
      <View style={styles.body}>
        <View style={styles.row}>
          <Text style={styles.number} numberOfLines={1} maxFontSizeMultiplier={1.3}>
            {item.equipment_number}
          </Text>
          {item.esd_required && (
            <View style={styles.esd}>
              <Text style={styles.esdText}>ESD</Text>
            </View>
          )}
        </View>
        <Text style={styles.sub} numberOfLines={1} maxFontSizeMultiplier={1.3}>
          {[item.model, item.category_name].filter(Boolean).join(" · ") || "—"}
        </Text>
        <View style={styles.row}>
          <Text style={[styles.status, { color: style.color }]} maxFontSizeMultiplier={1.3}>
            {style.label}
            {period ? ` · ${periodLabel(period)}` : ""}
          </Text>
          {detail && (
            <Text style={[styles.detail, { color: style.color }]} maxFontSizeMultiplier={1.3}>
              {detail}
            </Text>
          )}
        </View>
        {waiting && status !== "pending" && (
          <Text style={styles.waiting} maxFontSizeMultiplier={1.3}>
            PM waiting for approval
          </Text>
        )}
      </View>
    </Pressable>
  );
}

const styles = StyleSheet.create({
  card: {
    flex: 1,
    flexDirection: "row",
    minHeight: 120,
    borderRadius: PmsSizes.radius,
    backgroundColor: PmsColors.surface,
    borderWidth: 1,
    borderColor: PmsColors.border,
    overflow: "hidden",
  },
  pressed: { backgroundColor: "#E0F0FA" },
  accent: { width: 8 },
  body: { flex: 1, padding: PmsSizes.gap, gap: 6 },
  row: { flexDirection: "row", alignItems: "center", justifyContent: "space-between", gap: 8 },
  number: { flexShrink: 1, fontSize: 20, fontWeight: "700", color: PmsColors.text },
  sub: { fontSize: 16, color: PmsColors.textSecondary },
  status: { flexShrink: 1, fontSize: 16, fontWeight: "700" },
  detail: { fontSize: 16, fontWeight: "600" },
  esd: { paddingHorizontal: 8, paddingVertical: 2, borderRadius: 6, backgroundColor: PmsColors.esd },
  esdText: { fontSize: 13, fontWeight: "800", color: PmsColors.textOnPrimary },
  waiting: { fontSize: 14, color: PmsColors.pending, fontWeight: "600" },
});

