class EquipmentProfileSerializer(serializers.ModelSerializer):
    model = serializers.CharField(source='equipment_model.model', read_only=True, default=None)
    part_number = serializers.CharField(source='equipment_model.part_number', read_only=True, default=None)
    is_esd = serializers.SerializerMethodField()
    category = serializers.SerializerMethodField()
    periods = serializers.SerializerMethodField()
    esd_reading = serializers.SerializerMethodField()
    esd_status_code = serializers.SerializerMethodField()

    class Meta:
        model = Equipment
        fields = [
            'equipment_number', 'model', 'part_number', 'is_esd',
            'category', 'periods', 'esd_reading', 'esd_status_code',
        ]

    def _resolve_esd_source(self, obj):
        cache = self.__dict__.setdefault('_esd_source_cache', {})
        if obj.pk not in cache:
            cache[obj.pk] = resolve_esd_source(obj) if resolve_esd_spec(obj) else None
        return cache[obj.pk]

    def get_is_esd(self, obj):
        return resolve_esd_spec(obj) is not None

    def get_category(self, obj):
        cat = obj.equipment_model.category if obj.equipment_model_id else None
        if not cat:
            return None
        return {
            'id': cat.id,
            'name': cat.name,
            'category_type': cat.category_type,
            'production_area': obj.production_area.name if obj.production_area_id else None,
            'usage_control_enabled': cat.usage_control_enabled,
        }

    def get_pm_checklist(self, obj):
        checklist = obj.equipment_model.pm_checklist if obj.equipment_model_id else None
        if not checklist:
            return None
        return {'id': checklist.id, 'name': checklist.name}

    def get_periods(self, obj):
        now = timezone.now()

        pending_by_period = {}
        for rec in getattr(obj, 'pending_records', []):
            pending_by_period.setdefault(rec.pm_period_id, rec)

        result = []
        for schedule in obj.pm_schedules.all():
            next_pm = schedule.next_pm_date
            is_overdue = next_pm is not None and next_pm < now
            days_until_due = int((next_pm - now).total_seconds() // 86400) if next_pm is not None else None
            pending = pending_by_period.get(schedule.pm_period_id)
            result.append({
                'pm_period': schedule.pm_period_id,
                'period_name': schedule.pm_period.period_name,
                'is_esd_source': bool(getattr(schedule.pm_period, 'esd_sops', None)),
                'last_pm_date': schedule.last_pm_date,
                'next_pm_date': next_pm,
                'is_overdue': is_overdue,
                'days_until_due': days_until_due,
                'pending_approval': pending is not None,
                'pending_record_id': str(pending.id) if pending else None,
                'pending_approval_step': pending.current_workflow_step.name if pending and pending.current_workflow_step else None,
            })
        return result

    def get_esd_reading(self, obj):
        result = self._resolve_esd_source(obj)
        if result is None or not result.ok:
            return None
        return {k: v for k, v in result.data.items() if k not in ('equipment_number', 'model_name')}

    def get_esd_status_code(self, obj):
        result = self._resolve_esd_source(obj)
        if result is None:
            return None

        if request.method == 'POST':
            serializer = EsdMeasurementCreateSerializer(data=request.data)
            serializer.is_valid(raise_exception=True)
            measurement = record_esd_measurement(equipment, measured_by=request.user, **serializer.validated_data)
            return Response(esd_label_data(measurement), status=status.HTTP_201_CREATED)

        latest = resolve_esd_source(equipment)
        return Response({
            'equipment_number': equipment.equipment_number,
            'model_name': getattr(equipment.equipment_model, 'model', '') or '',
            'spec': esd_spec_data(spec),
            'latest': latest.data if latest.ok else None,
        })

    @action(detail=True, methods=['get'], url_path='profile')
    def profile(self, request, equipment_number=None):
        equipment = self.get_object()
        serializer = EquipmentProfileSerializer(equipment, context={'request': request})
        return Response(serializer.data)

    @action(detail=False, methods=['post'], url_path='bulk-generate')
    def bulk_generate(self, request):
        serializer = EquipmentBulkGenerateSerializer(data=request.data, context={'request': request})
        serializer.is_valid(raise_exception=True)
