import { api } from "@/lib/api";

export type PeriodSummary = {
  schedule_id: number;
  pm_period: number;
  period_name: string;
  custom_period_name: string | null;
  last_pm_date: string | null;
  next_pm_date: string | null;
  is_overdue: boolean;
  days_until_due: number | null;
  pending_approval: boolean;
  pending_approval_step: string | null;
};

export type EquipmentSummary = {
  id: number;
  equipment_number: string;
  model: string | null;
  category: number | null;
  category_name: string | null;
  location: string | null;
  station: string | null;
  periods: PeriodSummary[];
  esd_required: boolean;
};

export async function fetchEquipmentSummary(
  area: string,
): Promise<EquipmentSummary[]> {
  const { data } = await api.get<EquipmentSummary[]>("equipments/pm-summary/", {
    params: { prod_area_name: area },
  });
  return data;
}

export const WARNING_DAYS = 7;

export type PmStatus = "overdue" | "due" | "new" | "pending" | "on_time";

export const STATUS_RANK: Record<PmStatus, number> = {
  overdue: 0,
  due: 1,
  new: 2,
  pending: 3,
  on_time: 4,
};

export function periodStatus(p: PeriodSummary): PmStatus {
  if (p.is_overdue) return "overdue";
  if (p.days_until_due != null && p.days_until_due <= WARNING_DAYS)
    return "due";
  if (p.days_until_due != null) return "on_time";
  if (p.pending_approval && p.last_pm_date === null) return "pending";
  return "new";
}

export function periodLabel(p: PeriodSummary): string {
  return p.custom_period_name || p.period_name;
}

export function equipmentStatus(e: EquipmentSummary): {
  status: PmStatus;
  period: PeriodSummary | null;
} {
  let worst: { status: PmStatus; period: PeriodSummary | null } = {
    status: "new",
    period: null,
  };
  for (const p of e.periods) {
    const s = periodStatus(p);
    if (worst.period === null || STATUS_RANK[s] < STATUS_RANK[worst.status])
      worst = { status: s, period: p };
  }
  return worst;
}

