import { CameraView, useCameraPermissions, type BarcodeScanningResult } from "expo-camera";
import { router, useFocusEffect } from "expo-router";
import { useCallback, useRef, useState } from "react";
import { KeyboardAvoidingView, Linking, ScrollView, StyleSheet, Text, View } from "react-native";
import { SafeAreaView } from "react-native-safe-area-context";

import { PmsButton } from "@/components/pms/button";
import { PmsTextField } from "@/components/pms/text-field";
import { PmsColors, PmsSizes } from "@/constants/pms-theme";

/** The label QR holds the equipment number; tolerate stray whitespace or a URL ending in it. */
function equipmentNumberFrom(text: string): string {
  const trimmed = text.trim();
  return trimmed.includes("/") ? trimmed.replace(/\/+$/, "").split("/").pop()!.trim() : trimmed;
}

export default function ScanScreen() {
  const [permission, requestPermission] = useCameraPermissions();
  const [focused, setFocused] = useState(false);
  const [torch, setTorch] = useState(false);
  const [manual, setManual] = useState("");
  // The camera reports the same code many times a second; open the detail screen once.
  const handled = useRef(false);

  // Camera runs only while this screen is visible, and scanning re-arms when coming back.
  useFocusEffect(
    useCallback(() => {
      handled.current = false;
      setFocused(true);
      return () => {
        setFocused(false);
        setTorch(false);
      };
    }, []),
  );

  function open(raw: string) {
    const number = equipmentNumberFrom(raw);
    if (!number || handled.current) return;
    handled.current = true;
    router.push({ pathname: "/equipment/[number]", params: { number } });
  }

  function onScanned(result: BarcodeScanningResult) {
    open(result.data);
  }

  return (
    <SafeAreaView style={styles.screen}>
      <View style={styles.cameraSide}>
        {permission?.granted ? (
          <>
            <CameraView
              style={StyleSheet.absoluteFill}
              facing="back"
              active={focused}
              enableTorch={torch}
              barcodeScannerSettings={{ barcodeTypes: ["qr"] }}
              onBarcodeScanned={onScanned}
            />
            <View style={styles.overlay} pointerEvents="none">
              <View style={styles.frame} />
              <Text style={styles.overlayText}>Point at the QR code on the equipment label</Text>
            </View>
          </>
        ) : (
          <View style={styles.noCamera}>
            <Text style={styles.noCameraText}>Camera access is needed to scan QR codes.</Text>
            {permission && !permission.canAskAgain ? (
              <PmsButton title="Open settings" onPress={() => Linking.openSettings()} />
            ) : (
              <PmsButton title="Allow camera" onPress={requestPermission} />
            )}
          </View>
        )}
      </View>

      <KeyboardAvoidingView style={styles.panel} behavior="height">
        <ScrollView contentContainerStyle={styles.panelContent} keyboardShouldPersistTaps="handled">
          <Text style={styles.title}>Scan QR</Text>
          {permission?.granted && (
            <PmsButton
              title={torch ? "Light off" : "Light on"}
              variant="secondary"
              onPress={() => setTorch((t) => !t)}
            />
          )}
          <View style={styles.divider} />
          <PmsTextField
            label="Or type the equipment number"
            value={manual}
            onChangeText={setManual}
            autoCapitalize="characters"
            autoCorrect={false}
            returnKeyType="go"
            onSubmitEditing={() => open(manual)}
          />
          <PmsButton title="Open" onPress={() => open(manual)} disabled={manual.trim() === ""} />
          <PmsButton title="‹ Back" variant="secondary" onPress={() => router.back()} />
        </ScrollView>
      </KeyboardAvoidingView>
    </SafeAreaView>
  );
}

const styles = StyleSheet.create({
  screen: { flex: 1, flexDirection: "row", backgroundColor: PmsColors.background },
  cameraSide: { flex: 3, backgroundColor: "#000" },
  overlay: { ...StyleSheet.absoluteFillObject, alignItems: "center", justifyContent: "center", gap: PmsSizes.gap },
  frame: { width: 280, height: 280, borderWidth: 4, borderColor: "#FFFFFF", borderRadius: 24 },
  overlayText: {
    fontSize: 18,
    fontWeight: "600",
    color: "#FFFFFF",
    backgroundColor: "rgba(0,0,0,0.55)",
    paddingHorizontal: 16,
    paddingVertical: 8,
    borderRadius: 8,
  },
  noCamera: { flex: 1, alignItems: "center", justifyContent: "center", gap: PmsSizes.gap, padding: PmsSizes.pad },
  noCameraText: { fontSize: 18, color: "#FFFFFF", textAlign: "center" },
  panel: { flex: 2 },
  panelContent: { padding: PmsSizes.pad, gap: PmsSizes.gap },
  title: { fontSize: 28, fontWeight: "700", color: PmsColors.text },
  divider: { height: 1, backgroundColor: PmsColors.border },
});

