import { DefaultTheme, Stack, ThemeProvider } from "expo-router";
import * as SplashScreen from "expo-splash-screen";
import { StatusBar } from "expo-status-bar";
import { useEffect } from "react";

import { PmsColors } from "@/constants/pms-theme";
import { SessionProvider, useSession } from "@/lib/session";

SplashScreen.preventAutoHideAsync();

const theme = {
  ...DefaultTheme,
  colors: {
    ...DefaultTheme.colors,
    primary: PmsColors.primary,
    background: PmsColors.background,
  },
};

function RootStack() {
  const { ready, member, area } = useSession();

  useEffect(() => {
    if (ready) SplashScreen.hideAsync();
  }, [ready]);

  if (!ready) return null;
  const signedIn = member !== null;

  return (
    <Stack screenOptions={{ headerShown: false }}>
      <Stack.Protected guard={signedIn && area !== null}>
        <Stack.Screen name="index" />
        <Stack.Screen name="equipment/[number]" />
      </Stack.Protected>
      <Stack.Protected guard={signedIn}>
        <Stack.Screen name="select-area" />
      </Stack.Protected>
      <Stack.Protected guard={!signedIn}>
        <Stack.Screen name="sign-in" />
        <Stack.Screen
          name="server-settings"
          options={{ presentation: "modal" }}
        />
      </Stack.Protected>
    </Stack>
  );
}

export default function RootLayout() {
  return (
    <ThemeProvider value={theme}>
      <SessionProvider>
        <StatusBar style="dark" />
        <RootStack />
      </SessionProvider>
    </ThemeProvider>
  );
}

import { router } from "expo-router";
import { useCallback, useEffect, useMemo, useState } from "react";
import {
  ActivityIndicator,
  FlatList,
  Pressable,
  RefreshControl,
  ScrollView,
  StyleSheet,
  Text,
  TextInput,
  useWindowDimensions,
  View,
} from "react-native";
import { SafeAreaView } from "react-native-safe-area-context";

import { PmsButton } from "@/components/pms/button";
import { EquipmentCard } from "@/components/pms/equipment-card";
import { PmsColors, PmsSizes } from "@/constants/pms-theme";
import { errorMessage } from "@/lib/api";
import {
  equipmentStatus,
  fetchEquipmentSummary,
  STATUS_RANK,
  type EquipmentSummary,
} from "@/lib/equipment";
import { useSession } from "@/lib/session";

const ALL = "__all__";
const CARD_MIN_WIDTH = 340;

export default function HomeScreen() {
  const { member, area, signOut } = useSession();
  const canChangeArea = (member?.production_area_names.length ?? 0) > 1;

  return (
    <SafeAreaView style={styles.screen} edges={["top", "left", "right"]}>
      <View style={styles.bar}>
        <View style={styles.flex}>
          <Text style={styles.area}>{area}</Text>
          <Text style={styles.who}>{member?.name ?? member?.username}</Text>
        </View>
        <View style={styles.actions}>
          {canChangeArea && (
            <PmsButton
              title="Change area"
              variant="secondary"
              onPress={() => router.push("/select-area")}
            />
          )}
          <PmsButton title="Sign out" variant="secondary" onPress={signOut} />
        </View>
      </View>
      {area && <EquipmentList key={area} area={area} />}
    </SafeAreaView>
  );
}

function EquipmentList({ area }: { area: string }) {
  const [items, setItems] = useState<EquipmentSummary[] | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [refreshing, setRefreshing] = useState(false);
  const [category, setCategory] = useState(ALL);
  const [query, setQuery] = useState("");
  const { width } = useWindowDimensions();
  const columns = Math.max(
    1,
    Math.floor((width - PmsSizes.pad * 2) / CARD_MIN_WIDTH),
  );

  const load = useCallback(
    () =>
      fetchEquipmentSummary(area).then(
        (data) => {
          setItems(data);
          setError(null);
        },
        (e) => setError(errorMessage(e)),
      ),
    [area],
  );

  useEffect(() => {
    load();
  }, [load]);

  async function refresh() {
    setRefreshing(true);
    await load();
    setRefreshing(false);
  }

  const categories = useMemo(() => {
    const names = new Set(
      (items ?? []).map((e) => e.category_name).filter((n): n is string => !!n),
    );
    return [...names].sort();
  }, [items]);

  // Most urgent first, then by number.
  const visible = useMemo(() => {
    const q = query.trim().toLowerCase();
    return (items ?? [])
      .filter((e) => category === ALL || e.category_name === category)
      .filter(
        (e) =>
          q === "" ||
          e.equipment_number.toLowerCase().includes(q) ||
          (e.model ?? "").toLowerCase().includes(q),
      )
      .map((e) => ({ e, rank: STATUS_RANK[equipmentStatus(e).status] }))
      .sort(
        (a, b) =>
          a.rank - b.rank ||
          a.e.equipment_number.localeCompare(b.e.equipment_number),
      )
      .map(({ e }) => e);
  }, [items, category, query]);

  if (items === null) {
    return (
      <View style={styles.center}>
        {error ? (
          <>
            <Text style={styles.error}>{error}</Text>
            <PmsButton title="Retry" onPress={refresh} loading={refreshing} />
          </>
        ) : (
          <ActivityIndicator size="large" color={PmsColors.primary} />
        )}
      </View>
    );
  }

  return (
    <View style={styles.flex}>
      <View style={styles.filters}>
        <TextInput
          value={query}
          onChangeText={setQuery}
          placeholder="Search equipment number or model"
          placeholderTextColor={PmsColors.textSecondary}
          autoCapitalize="none"
          autoCorrect={false}
          clearButtonMode="while-editing"
          maxFontSizeMultiplier={1.3}
          style={styles.search}
        />
        <ScrollView
          horizontal
          showsHorizontalScrollIndicator={false}
          contentContainerStyle={styles.chips}
        >
          {[ALL, ...categories].map((name) => (
            <Pressable
              key={name}
              accessibilityRole="button"
              accessibilityState={{ selected: category === name }}
              onPress={() => setCategory(name)}
              style={[styles.chip, category === name && styles.chipOn]}
            >
              <Text
                style={[
                  styles.chipText,
                  category === name && styles.chipTextOn,
                ]}
                maxFontSizeMultiplier={1.3}
              >
                {name === ALL ? `All (${items.length})` : name}
              </Text>
            </Pressable>
          ))}
        </ScrollView>
      </View>

      {error && <Text style={[styles.error, styles.banner]}>{error}</Text>}

      <FlatList
        key={columns}
        data={visible}
        numColumns={columns}
        keyExtractor={(e) => e.equipment_number}
        renderItem={({ item }) => (
          <View style={[styles.cell, { maxWidth: `${100 / columns}%` }]}>
            <EquipmentCard
              item={item}
              onPress={() =>
                router.push({
                  pathname: "/equipment/[number]",
                  params: { number: item.equipment_number },
                })
              }
            />
          </View>
        )}
        contentContainerStyle={styles.list}
        refreshControl={
          <RefreshControl
            refreshing={refreshing}
            onRefresh={refresh}
            colors={[PmsColors.primary]}
          />
        }
        keyboardShouldPersistTaps="handled"
        ListEmptyComponent={
          <Text style={styles.empty}>
            {items.length === 0
              ? "No equipment in this area."
              : "No equipment matches the search."}
          </Text>
        }
      />
    </View>
  );
}

const styles = StyleSheet.create({
  screen: { flex: 1, backgroundColor: PmsColors.background },
  flex: { flex: 1 },
  bar: {
    flexDirection: "row",
    justifyContent: "space-between",
    alignItems: "center",
    gap: PmsSizes.gap,
    padding: PmsSizes.gap,
    paddingHorizontal: PmsSizes.pad,
    backgroundColor: PmsColors.surface,
    borderBottomWidth: 1,
    borderBottomColor: PmsColors.border,
  },
  area: { fontSize: 24, fontWeight: "700", color: PmsColors.text },
  who: { fontSize: 16, color: PmsColors.textSecondary },
  actions: { flexDirection: "row", gap: PmsSizes.gap },
  filters: {
    paddingHorizontal: PmsSizes.pad,
    paddingTop: PmsSizes.gap,
    gap: 12,
  },
  search: {
    minHeight: PmsSizes.touch + 8,
    paddingHorizontal: 16,
    borderWidth: 2,
    borderColor: PmsColors.border,
    borderRadius: PmsSizes.radius,
    backgroundColor: PmsColors.surface,
    fontSize: 18,
    color: PmsColors.text,
  },
  chips: { gap: 10 },
  chip: {
    minHeight: PmsSizes.touch,
    paddingHorizontal: 20,
    borderRadius: PmsSizes.touch / 2,
    borderWidth: 2,
    borderColor: PmsColors.border,
    backgroundColor: PmsColors.surface,
    justifyContent: "center",
  },
  chipOn: {
    backgroundColor: PmsColors.primary,
    borderColor: PmsColors.primary,
  },
  chipText: { fontSize: 16, fontWeight: "600", color: PmsColors.text },
  chipTextOn: { color: PmsColors.textOnPrimary },
  list: { padding: PmsSizes.pad - 8, paddingBottom: PmsSizes.pad * 2 },
  cell: { flex: 1, padding: 8 },
  center: {
    flex: 1,
    alignItems: "center",
    justifyContent: "center",
    gap: PmsSizes.gap,
    padding: PmsSizes.pad,
  },
  error: { fontSize: 16, color: PmsColors.danger, textAlign: "center" },
  banner: { paddingHorizontal: PmsSizes.pad, paddingTop: 8 },
  empty: {
    fontSize: 18,
    color: PmsColors.textSecondary,
    textAlign: "center",
    marginTop: PmsSizes.pad * 2,
  },
});

