import { CameraView } from "expo-camera";
import { useRef, useState } from "react";
import { ActivityIndicator, Modal, Pressable, StyleSheet, Text, View } from "react-native";
import { SafeAreaView } from "react-native-safe-area-context";

import { PmsButton } from "@/components/pms/button";
import { PmsColors, PmsSizes } from "@/constants/pms-theme";

type Props = {
  visible: boolean;
  title: string;
  onCancel: () => void;
  onCaptured: (uri: string) => void;
};

/** Full-screen camera for a step photo. Camera permission is asked on the scan screen or here by Android. */
export function PhotoCapture({ visible, title, onCancel, onCaptured }: Props) {
  const camera = useRef<CameraView>(null);
  const [busy, setBusy] = useState(false);

  async function shoot() {
    if (!camera.current || busy) return;
    setBusy(true);
    try {
      // 0.5 keeps a tablet photo well under 1 MB for the upload.
      const photo = await camera.current.takePictureAsync({ quality: 0.5 });
      onCaptured(photo.uri);
    } finally {
      setBusy(false);
    }
  }

  return (
    <Modal visible={visible} animationType="slide" onRequestClose={onCancel} supportedOrientations={["landscape"]}>
      <SafeAreaView style={styles.screen}>
        {visible && <CameraView ref={camera} style={StyleSheet.absoluteFill} facing="back" />}
        <View style={styles.side}>
          <Text style={styles.title} numberOfLines={3}>
            {title}
          </Text>
          <Pressable
            accessibilityRole="button"
            accessibilityLabel="Take photo"
            onPress={shoot}
            style={({ pressed }) => [styles.shutter, pressed && styles.shutterPressed]}>
            {busy ? <ActivityIndicator color={PmsColors.primary} /> : <View style={styles.shutterInner} />}
          </Pressable>
          <PmsButton title="Cancel" variant="secondary" onPress={onCancel} />
        </View>
      </SafeAreaView>
    </Modal>
  );
}

const styles = StyleSheet.create({
  screen: { flex: 1, backgroundColor: "#000" },
  side: {
    position: "absolute",
    right: 0,
    top: 0,
    bottom: 0,
    width: 220,
    padding: PmsSizes.pad,
    justifyContent: "space-between",
    alignItems: "stretch",
    backgroundColor: "rgba(0,0,0,0.5)",
  },
  title: { fontSize: 18, fontWeight: "700", color: "#FFFFFF" },
  shutter: {
    alignSelf: "center",
    width: 96,
    height: 96,
    borderRadius: 48,
    borderWidth: 6,
    borderColor: "#FFFFFF",
    alignItems: "center",
    justifyContent: "center",
  },
  shutterPressed: { opacity: 0.6 },
  shutterInner: { width: 68, height: 68, borderRadius: 34, backgroundColor: "#FFFFFF" },
});

