import { useCameraPermissions } from "expo-camera";
import { Image } from "expo-image";
import { router, useLocalSearchParams } from "expo-router";
import { useEffect, useState } from "react";
import {
  ActivityIndicator,
  Alert,
  KeyboardAvoidingView,
  Pressable,
  ScrollView,
  StyleSheet,
  Text,
  TextInput,
  View,
} from "react-native";
import { SafeAreaView } from "react-native-safe-area-context";

import { PmsButton } from "@/components/pms/button";
import { PhotoCapture } from "@/components/pms/photo-capture";
import { PmsColors, PmsSizes } from "@/constants/pms-theme";
import { errorMessage } from "@/lib/api";
import {
  EMPTY_ANSWER,
  fetchSops,
  isStepDone,
  numberPasses,
  parseNumber,
  submitPm,
  type PmSop,
  type StepAnswer,
  type SubmittedPm,
} from "@/lib/pm";
import { useSession } from "@/lib/session";

type Params = { number: string; period: string; name?: string; equipmentId: string };

export default function PerformPmScreen() {
  const { number, period, name, equipmentId } = useLocalSearchParams<Params>();
  const { area } = useSession();
  const [sops, setSops] = useState<PmSop[] | null>(null);
  const [loadError, setLoadError] = useState<string | null>(null);
  const [answers, setAnswers] = useState<Record<number, StepAnswer>>({});
  const [notes, setNotes] = useState("");
  const [capturing, setCapturing] = useState<PmSop | null>(null);
  const [submitting, setSubmitting] = useState(false);
  const [submitError, setSubmitError] = useState<string | null>(null);
  const [result, setResult] = useState<SubmittedPm | null>(null);
  const [cameraPermission, requestCameraPermission] = useCameraPermissions();

  useEffect(() => {
    if (!area) return;
    fetchSops(Number(period), area).then(setSops, (e) => setLoadError(errorMessage(e)));
  }, [period, area]);

  const doneCount = sops?.filter((s) => isStepDone(s, answers[s.id] ?? EMPTY_ANSWER)).length ?? 0;
  const allDone = sops !== null && sops.length > 0 && doneCount === sops.length;
  const touched = Object.keys(answers).length > 0 || notes !== "";

  function update(sopId: number, change: Partial<StepAnswer>) {
    setAnswers((prev) => ({ ...prev, [sopId]: { ...(prev[sopId] ?? EMPTY_ANSWER), ...change } }));
  }

  async function takePhoto(sop: PmSop) {
    if (!cameraPermission?.granted) {
      const res = await requestCameraPermission();
      if (!res.granted) {
        Alert.alert("Camera not allowed", "Allow camera access for PMS+ in Android settings to take step photos.");
        return;
      }
    }
    setCapturing(sop);
  }

  function leave() {
    if (!touched || result) return router.back();
    Alert.alert("Discard this PM?", "The results you entered will be lost.", [
      { text: "Keep working", style: "cancel" },
      { text: "Discard", style: "destructive", onPress: () => router.back() },
    ]);
  }

  async function submit() {
    if (!sops || !allDone) return;
    setSubmitting(true);
    setSubmitError(null);
    try {
      setResult(await submitPm({ equipmentId, pmPeriod: Number(period), notes: notes.trim(), sops, answers }));
    } catch (e) {
      setSubmitError(errorMessage(e));
    } finally {
      setSubmitting(false);
    }
  }

  const title = `${name ?? "PM"} · ${number}`;

  return (
    <SafeAreaView style={styles.screen} edges={["top", "left", "right"]}>
      <View style={styles.bar}>
        <PmsButton title={result ? "‹ Back" : "Cancel"} variant="secondary" onPress={leave} />
        <View style={styles.flex}>
          <Text style={styles.title} numberOfLines={1}>
            {title}
          </Text>
          {sops && !result && (
            <Text style={styles.subtitle}>
              {doneCount} of {sops.length} steps done
            </Text>
          )}
        </View>
      </View>
      {sops && !result && (
        <View style={styles.progressTrack}>
          <View style={[styles.progressFill, { width: `${(doneCount / Math.max(sops.length, 1)) * 100}%` }]} />
        </View>
      )}

      {result ? (
        <ResultPanel result={result} />
      ) : sops === null ? (
        <View style={styles.center}>
          {loadError ? <Text style={styles.error}>{loadError}</Text> : <ActivityIndicator size="large" color={PmsColors.primary} />}
        </View>
      ) : sops.length === 0 ? (
        <View style={styles.center}>
          <Text style={styles.muted}>This period has no checklist steps. Ask your manager to set them up on the web.</Text>
        </View>
      ) : (
        <KeyboardAvoidingView style={styles.flex} behavior="height">
          <ScrollView contentContainerStyle={styles.content} keyboardShouldPersistTaps="handled">
            {sops.map((sop, i) => (
              <StepCard
                key={sop.id}
                index={i + 1}
                sop={sop}
                answer={answers[sop.id] ?? EMPTY_ANSWER}
                onChange={(change) => update(sop.id, change)}
                onTakePhoto={() => takePhoto(sop)}
              />
            ))}

            <View style={styles.card}>
              <Text style={styles.stepName}>Notes (optional)</Text>
              <TextInput
                value={notes}
                onChangeText={setNotes}
                multiline
                placeholder="Anything the approver should know"
                placeholderTextColor={PmsColors.textSecondary}
                style={[styles.input, styles.multiline]}
              />
            </View>

            {submitError && <Text style={styles.error}>{submitError}</Text>}
            <PmsButton
              title={allDone ? "Submit PM" : `Complete all steps (${doneCount}/${sops.length})`}
              onPress={submit}
              disabled={!allDone}
              loading={submitting}
            />
          </ScrollView>
        </KeyboardAvoidingView>
      )}

      <PhotoCapture
        visible={capturing !== null}
        title={capturing ? capturing.name : ""}
        onCancel={() => setCapturing(null)}
        onCaptured={(uri) => {
          if (capturing) update(capturing.id, { photoUri: uri });
          setCapturing(null);
        }}
      />
    </SafeAreaView>
  );
}

type StepProps = {
  index: number;
  sop: PmSop;
  answer: StepAnswer;
  onChange: (change: Partial<StepAnswer>) => void;
  onTakePhoto: () => void;
};

function StepCard({ index, sop, answer, onChange, onTakePhoto }: StepProps) {
  const done = isStepDone(sop, answer);
  return (
    <View style={[styles.card, done && styles.cardDone]}>
      <View style={styles.stepHead}>
        <View style={[styles.stepNo, done && styles.stepNoDone]}>
          <Text style={styles.stepNoText}>{done ? "✓" : index}</Text>
        </View>
        <View style={styles.flex}>
          <Text style={styles.stepName}>{sop.name}</Text>
          {sop.description ? <Text style={styles.muted}>{sop.description}</Text> : null}
        </View>
      </View>

      {sop.input_type === "checkbox" && (
        <View style={styles.row}>
          <Choice label="OK" selected={answer.ok === true} color={PmsColors.onTime} onPress={() => onChange({ ok: true })} />
          <Choice label="Not OK" selected={answer.ok === false} color={PmsColors.overdue} onPress={() => onChange({ ok: false })} />
        </View>
      )}

      {sop.input_type === "number_range" && <NumberInput sop={sop} value={answer.number} onChange={(number) => onChange({ number })} />}

      {sop.input_type === "text" && (
        <TextInput
          value={answer.text}
          onChangeText={(text) => onChange({ text })}
          multiline
          placeholder="Enter result"
          placeholderTextColor={PmsColors.textSecondary}
          style={[styles.input, styles.multiline]}
        />
      )}

      {sop.requires_image && (
        <View style={styles.row}>
          {answer.photoUri && <Image source={{ uri: answer.photoUri }} style={styles.thumb} contentFit="cover" />}
          <PmsButton
            title={answer.photoUri ? "Retake photo" : "Take photo (required)"}
            variant={answer.photoUri ? "secondary" : "primary"}
            onPress={onTakePhoto}
          />
        </View>
      )}
    </View>
  );
}

function NumberInput({ sop, value, onChange }: { sop: PmSop; value: string; onChange: (v: string) => void }) {
  const parsed = parseNumber(value);
  const pass = parsed === null ? null : numberPasses(sop, parsed);
  const range =
    sop.min_value != null && sop.max_value != null
      ? `${sop.min_value} – ${sop.max_value}`
      : sop.min_value != null
        ? `≥ ${sop.min_value}`
        : sop.max_value != null
          ? `≤ ${sop.max_value}`
          : "any value";

  return (
    <View style={styles.row}>
      <TextInput
        value={value}
        onChangeText={onChange}
        keyboardType="decimal-pad"
        placeholder="0"
        placeholderTextColor={PmsColors.textSecondary}
        style={[styles.input, styles.numberInput]}
      />
      <Text style={styles.unit}>{sop.unit ?? ""}</Text>
      <View style={styles.flex}>
        <Text style={styles.muted}>Spec: {range} {sop.unit ?? ""}</Text>
      </View>
      {pass !== null && (
        <View style={[styles.verdict, { backgroundColor: pass ? PmsColors.onTime : PmsColors.overdue }]}>
          <Text style={styles.verdictText}>{pass ? "PASS" : "FAIL"}</Text>
        </View>
      )}
    </View>
  );
}

function Choice({ label, selected, color, onPress }: { label: string; selected: boolean; color: string; onPress: () => void }) {
  return (
    <Pressable
      accessibilityRole="radio"
      accessibilityState={{ selected }}
      onPress={onPress}
      style={[styles.choice, { borderColor: color }, selected && { backgroundColor: color }]}>
      <Text style={[styles.choiceText, { color: selected ? PmsColors.textOnPrimary : color }]}>{label}</Text>
    </Pressable>
  );
}

function ResultPanel({ result }: { result: SubmittedPm }) {
  const approved = result.status === "approved";
  const color = approved ? PmsColors.onTime : PmsColors.pending;
  let message: string;
  if (approved) {
    message = result.approval_bypassed ? "Approved automatically — every step passed." : "Approved.";
  } else {
    message = `Waiting for approval${result.current_workflow_step ? ` at "${result.current_workflow_step.name}"` : ""}.`;
  }

  return (
    <View style={styles.center}>
      <View style={[styles.resultBadge, { backgroundColor: color }]}>
        <Text style={styles.resultBadgeText}>{approved ? "✓" : "…"}</Text>
      </View>
      <Text style={styles.resultTitle}>PM submitted</Text>
      <Text style={styles.resultText}>{message}</Text>
      {result.is_passed === false && (
        <Text style={[styles.resultText, { color: PmsColors.overdue }]}>
          Some steps failed, so this PM must be reviewed.
        </Text>
      )}
      <PmsButton title="Back to equipment" onPress={() => router.back()} />
    </View>
  );
}

const styles = StyleSheet.create({
  screen: { flex: 1, backgroundColor: PmsColors.background },
  flex: { flex: 1 },
  bar: {
    flexDirection: "row",
    alignItems: "center",
    gap: PmsSizes.gap,
    padding: PmsSizes.gap,
    paddingHorizontal: PmsSizes.pad,
    backgroundColor: PmsColors.surface,
  },
  title: { fontSize: 24, fontWeight: "700", color: PmsColors.text },
  subtitle: { fontSize: 16, color: PmsColors.textSecondary },
  progressTrack: { height: 6, backgroundColor: PmsColors.border },
  progressFill: { height: 6, backgroundColor: PmsColors.onTime },
  center: { flex: 1, alignItems: "center", justifyContent: "center", gap: PmsSizes.gap, padding: PmsSizes.pad },
  content: { padding: PmsSizes.pad, gap: PmsSizes.gap, width: "100%", maxWidth: 1000, alignSelf: "center" },
  error: { fontSize: 16, color: PmsColors.danger, textAlign: "center" },
  muted: { fontSize: 15, color: PmsColors.textSecondary },
  card: {
    backgroundColor: PmsColors.surface,
    borderRadius: PmsSizes.radius,
    borderWidth: 2,
    borderColor: PmsColors.border,
    padding: PmsSizes.gap + 4,
    gap: 14,
  },
  cardDone: { borderColor: PmsColors.onTime },
  stepHead: { flexDirection: "row", gap: 14, alignItems: "flex-start" },
  stepNo: {
    width: 40,
    height: 40,
    borderRadius: 20,
    backgroundColor: PmsColors.border,
    alignItems: "center",
    justifyContent: "center",
  },
  stepNoDone: { backgroundColor: PmsColors.onTime },
  stepNoText: { fontSize: 18, fontWeight: "800", color: PmsColors.textOnPrimary },
  stepName: { fontSize: 19, fontWeight: "700", color: PmsColors.text },
  row: { flexDirection: "row", alignItems: "center", gap: PmsSizes.gap },
  choice: {
    flex: 1,
    minHeight: PmsSizes.primaryButton,
    borderWidth: 3,
    borderRadius: PmsSizes.radius,
    alignItems: "center",
    justifyContent: "center",
  },
  choiceText: { fontSize: 20, fontWeight: "800" },
  input: {
    minHeight: PmsSizes.primaryButton,
    paddingHorizontal: 16,
    borderWidth: 2,
    borderColor: PmsColors.border,
    borderRadius: PmsSizes.radius,
    backgroundColor: PmsColors.surface,
    fontSize: 20,
    color: PmsColors.text,
  },
  multiline: { minHeight: 96, paddingTop: 12, textAlignVertical: "top" },
  numberInput: { width: 200, fontSize: 24, fontWeight: "700" },
  unit: { fontSize: 18, color: PmsColors.textSecondary },
  verdict: { paddingHorizontal: 18, paddingVertical: 10, borderRadius: PmsSizes.radius },
  verdictText: { fontSize: 20, fontWeight: "800", color: PmsColors.textOnPrimary },
  thumb: { width: 120, height: 90, borderRadius: 8, backgroundColor: PmsColors.border },
  resultBadge: { width: 96, height: 96, borderRadius: 48, alignItems: "center", justifyContent: "center" },
  resultBadgeText: { fontSize: 48, fontWeight: "800", color: PmsColors.textOnPrimary },
  resultTitle: { fontSize: 32, fontWeight: "700", color: PmsColors.text },
  resultText: { fontSize: 18, color: PmsColors.text, textAlign: "center" },
});

